const VS=[
  // TRISTEZA
  {a:'tristeza',c:'#6b8cba',t:'El Señor está cerca de los que tienen el corazón quebrantado, y salva a los de espíritu abatido.',r:'Salmos 34, 18',x:'El dolor no es abandono divino; Dios se acerca especialmente en el sufrimiento.'},
  {a:'tristeza',c:'#6b8cba',t:'Vengan a mí todos los que están fatigados y sobrecargados, y yo les daré descanso.',r:'Mateo 11, 28',x:'Jesús no pide que vengas cuando estés bien; llama precisamente al que carga con algo pesado.'},
  {a:'tristeza',c:'#6b8cba',t:'¿Por qué te abates, alma mía? ¿Por qué te agitas dentro de mí? Espera en Dios, pues he de alabarle todavía.',r:'Salmos 42, 11',x:'El salmista se habla a sí mismo en la angustia y se recuerda la esperanza.'},
  {a:'tristeza',c:'#6b8cba',t:'Él sana a los de corazón quebrantado y venda sus heridas.',r:'Salmos 147, 3',x:'Dios es el médico del alma; la sanación viene de arriba.'},
  {a:'tristeza',c:'#6b8cba',t:'Aunque cruce por oscuras quebradas, no temeré ningún mal, porque tú estás conmigo: tu vara y tu bastón me infunden confianza.',r:'Salmos 23, 4',x:'La oscuridad no es ausencia de Dios: Él camina junto al que atraviesa el dolor.'},
  {a:'tristeza',c:'#6b8cba',t:'Has cambiado mi luto en danza; quitaste mi lamento y me ceñiste de alegría.',r:'Salmos 30, 11',x:'La transformación del dolor en gozo es obra de Dios, no del tiempo solo.'},
  {a:'tristeza',c:'#6b8cba',t:'Los que sembraron con lágrimas cosecharán entre cantares.',r:'Salmos 126, 5',x:'Cada lágrima derramada con fe es semilla de una alegría futura.'},
  {a:'tristeza',c:'#6b8cba',t:'Dios secará las lágrimas de sus ojos: ya no habrá muerte, ni luto, ni llanto, ni dolor.',r:'Apocalipsis 21, 4',x:'La promesa última: Dios mismo secará cada lágrima con su propia mano.'},
  // ALEGRÍA
  {a:'alegria',c:'#c9a84c',t:'Este es el día que hizo el Señor; regocijémonos y alegrémonos en él.',r:'Salmos 118, 24',x:'Cada día es don divino y motivo de alabanza.'},
  {a:'alegria',c:'#c9a84c',t:'Alégrense siempre en el Señor. Vuelvo a insistir, alégrense.',r:'Filipenses 4, 4',x:'San Pablo escribe desde la cárcel: la alegría cristiana no depende de circunstancias.'},
  {a:'alegria',c:'#c9a84c',t:'El gozo del Señor es la fortaleza de ustedes.',r:'Nehemías 8, 10',x:'La alegría espiritual no es superficial: es fuente de fuerza interior.'},
  {a:'alegria',c:'#c9a84c',t:'Canten al Señor un cántico nuevo, porque ha hecho maravillas.',r:'Salmos 98, 1',x:'La alabanza es la respuesta natural del corazón que ha experimentado la gracia.'},
  {a:'alegria',c:'#c9a84c',t:'Me has dado a conocer los caminos de la vida; me llenarás de alegría con tu presencia.',r:'Hechos 2, 28',x:'La presencia de Dios es, en sí misma, fuente inagotable de gozo.'},
  {a:'alegria',c:'#c9a84c',t:'Regocíjense en el Señor siempre; otra vez lo digo: regocíjense.',r:'Filipenses 4, 4',x:'El imperativo de la alegría: no es opción sino vocación del cristiano.'},
  {a:'alegria',c:'#c9a84c',t:'Hasta ahora no han pedido nada en mi Nombre. Pidan y recibirán, y tendrán una alegría que será perfecta.',r:'Juan 16, 24',x:'Jesús desea que el gozo de sus discípulos sea completo, pleno, sin límites.'},
  {a:'alegria',c:'#c9a84c',t:'Les he dicho esto para que mi gozo sea el de ustedes, y ese gozo sea perfecto.',r:'Juan 15, 11',x:'El gozo de Jesús mismo quiere habitar en nosotros; esa es la promesa.'},
  // MIEDO
  {a:'miedo',c:'#8b6040',t:'No temas, porque yo estoy contigo, no te inquietes, porque yo soy tu Dios; yo te fortalezco y te ayudo, yo te sostengo con mi mano victoriosa.',r:'Isaías 41, 10',x:'Dios habla a Israel en el exilio. Su presencia es garantía contra el temor.'},
  {a:'miedo',c:'#8b6040',t:'El Señor es mi luz y mi salvación, ¿a quién temeré? El Señor es el baluarte de mi vida, ¿ante quién temblaré?',r:'Salmos 27, 1',x:'La fe en Dios transforma el miedo en confianza serena.'},
  {a:'miedo',c:'#8b6040',t:'No se angustien por nada, y en cualquier circunstancia recurran a la oración y a la súplica, acompañadas de acción de gracias, para presentar sus peticiones a Dios.',r:'Filipenses 4, 6',x:'La oración es el antídoto divino contra la ansiedad.'},
  {a:'miedo',c:'#8b6040',t:'En el amor no hay lugar para el temor: al contrario, el amor perfecto elimina el temor.',r:'1 Juan 4, 18',x:'El amor de Dios, cuando se acoge plenamente, disuelve el miedo.'},
  {a:'miedo',c:'#8b6040',t:'Si cruzas por las aguas, yo estaré contigo, y los ríos no te anegarán; si caminas por el fuego, no te quemarás, y las llamas no te abrasarán.',r:'Isaías 43, 2',x:'Dios no promete que no habrá tormentas; promete que no te hundirás en ellas.'},
  {a:'miedo',c:'#8b6040',t:'No temas, cree solamente.',r:'Marcos 5, 36',x:'Jesús lo dice en el momento más oscuro: cuando todo parece perdido, la fe es el único camino.'},
  {a:'miedo',c:'#8b6040',t:'Descarguen en él toda su preocupación, porque él tiene cuidado de ustedes.',r:'1 Pedro 5, 7',x:'La ansiedad no es para cargarla solo: puede depositarse en Dios, que cuida con ternura.'},
  // ESPERANZA
  {a:'esperanza',c:'#4a8c6b',t:'Yo conozco muy bien los planes que tengo proyectados sobre ustedes —oráculo del Señor—: son planes de prosperidad y no de desgracia, para asegurarles un porvenir y una esperanza.',r:'Jeremías 29, 11',x:'Dios habla al pueblo en el exilio: hay futuro aunque hoy no se vea.'},
  {a:'esperanza',c:'#4a8c6b',t:'Los que esperan en el Señor renuevan sus fuerzas, despliegan alas como las águilas; corren y no se agotan, avanzan y no se fatigan.',r:'Isaías 40, 31',x:'La esperanza no es pasividad: transforma y fortalece a quien la vive.'},
  {a:'esperanza',c:'#4a8c6b',t:'La esperanza no quedará defraudada, porque el amor de Dios ha sido derramado en nuestros corazones por el Espíritu Santo, que nos ha sido dado.',r:'Romanos 5, 5',x:'San Pablo enseña que la esperanza cristiana tiene fundamento sólido: el amor de Dios.'},
  {a:'esperanza',c:'#4a8c6b',t:'Yo lo puedo todo en aquel que me conforta.',r:'Filipenses 4, 13',x:'La fortaleza cristiana no viene de uno mismo sino de la comunión con Cristo.'},
  {a:'esperanza',c:'#4a8c6b',t:'Bendito el hombre que confía en el Señor, y cuya confianza es el Señor. Será como el árbol plantado junto a las aguas.',r:'Jeremías 17, 7-8',x:'La confianza en Dios da raíces profundas que resisten cualquier sequía o tormenta.'},
  {a:'esperanza',c:'#4a8c6b',t:'Tengo la certeza de que ni la muerte ni la vida, ni los ángeles ni los principados, ni lo presente ni lo futuro, ni ninguna otra criatura podrá separarnos jamás del amor de Dios, manifestado en Cristo Jesús, nuestro Señor.',r:'Romanos 8, 38-39',x:'La promesa más absoluta de San Pablo: nada en el universo puede romper ese amor.'},
  {a:'esperanza',c:'#4a8c6b',t:'El que comenzó en ustedes esta buena obra, la llevará a su cumplimiento hasta el día de Cristo Jesús.',r:'Filipenses 1, 6',x:'Dios no abandona lo que empieza: la obra de gracia en cada persona llegará a su plenitud.'},
  {a:'esperanza',c:'#4a8c6b',t:'Busquen primero el Reino de Dios y su justicia, y todo lo demás se les dará por añadidura.',r:'Mateo 6, 33',x:'La prioridad de Dios no deja al hombre sin lo necesario; la confianza tiene su fruto.'},
  // SOLEDAD
  {a:'soledad',c:'#7a6aac',t:'Aunque mi padre y mi madre me abandonen, el Señor me recibirá.',r:'Salmos 27, 10',x:'Incluso el abandono más doloroso no puede separarnos del amor de Dios.'},
  {a:'soledad',c:'#7a6aac',t:'Yo estoy con ustedes todos los días, hasta el fin del mundo.',r:'Mateo 28, 20',x:'Las últimas palabras de Jesús en Mateo son una promesa de compañía permanente.'},
  {a:'soledad',c:'#7a6aac',t:'¿Puede una madre olvidarse de su criatura? Aunque ella se olvidase, yo no te olvidaré.',r:'Isaías 49, 15',x:'Dios usa la imagen del amor materno para hablar de su fidelidad absoluta.'},
  {a:'soledad',c:'#7a6aac',t:'Yo estoy junto a la puerta y llamo: si alguien oye mi voz y me abre, entraré en su casa y cenaremos juntos.',r:'Apocalipsis 3, 20',x:'Jesús llama a la puerta del corazón: nadie que abra queda solo ni sin compañía.'},
  {a:'soledad',c:'#7a6aac',t:'¿A dónde iré para estar lejos de tu espíritu? ¿A dónde huiré de tu presencia?',r:'Salmos 139, 7',x:'No existe lugar, interior o exterior, donde Dios no esté. La soledad absoluta es imposible para el creyente.'},
  {a:'soledad',c:'#7a6aac',t:'No te dejaré ni te abandonaré.',r:'Josué 1, 5',x:'La promesa que Dios repite a lo largo de toda la Biblia: su presencia es permanente.'},
  // GRATITUD
  {a:'gratitud',c:'#b8860b',t:'Den gracias al Señor, porque es bueno, porque es eterna su misericordia.',r:'Salmos 136, 1',x:'El estribillo se repite 26 veces: la misericordia divina es inagotable.'},
  {a:'gratitud',c:'#b8860b',t:'Den gracias en toda ocasión, porque esta es la voluntad de Dios para ustedes en Cristo Jesús.',r:'1 Tesalonicenses 5, 18',x:'La gratitud no es solo por las cosas buenas: es actitud permanente del alma cristiana.'},
  {a:'gratitud',c:'#b8860b',t:'¿Qué pagaré al Señor por todos sus beneficios para conmigo?',r:'Salmos 116, 12',x:'El reconocimiento de los dones recibidos es el comienzo de la vida espiritual madura.'},
  {a:'gratitud',c:'#b8860b',t:'Bendice al Señor, alma mía, y nunca olvides sus beneficios.',r:'Salmos 103, 2',x:'El olvido es el enemigo de la gratitud; recordar los dones es un acto espiritual.'},
  {a:'gratitud',c:'#b8860b',t:'Sean agradecidos en toda circunstancia: esta es la voluntad de Dios en Cristo Jesús para con ustedes.',r:'1 Tesalonicenses 5, 18',x:'La gratitud en toda circunstancia revela un corazón que confía más allá de lo que ve.'},
  {a:'gratitud',c:'#b8860b',t:'¡Cuán preciosos me son, oh Dios, tus pensamientos! ¡Cuán grande es la suma de ellos!',r:'Salmos 139, 17',x:'Maravillarse ante Dios es la forma más elevada de gratitud.'},
  // FORTALEZA
  {a:'fortaleza',c:'#8b2020',t:'¡Sean fuertes y valientes! No tengan miedo ni tiemblen, porque el Señor, tu Dios, te acompaña, y él no te abandonará ni te dejará desamparado.',r:'Deuteronomio 31, 6',x:'Moisés despide al pueblo con estas palabras antes de su muerte.'},
  {a:'fortaleza',c:'#8b2020',t:'Fortalézcanse en el Señor y en la fuerza de su poder.',r:'Efesios 6, 10',x:'San Pablo invita a no apoyarse en la fuerza propia sino en la de Dios.'},
  {a:'fortaleza',c:'#8b2020',t:'El Señor es mi fortaleza y mi escudo; en él confía mi corazón.',r:'Salmos 28, 7',x:'La imagen de Dios como escudo y roca aparece repetidamente en los Salmos.'},
  {a:'fortaleza',c:'#8b2020',t:'El que persevere hasta el fin, se salvará.',r:'Mateo 24, 13',x:'La perseverancia en la fe, no la perfección, es lo que Jesús pide.'},
  {a:'fortaleza',c:'#8b2020',t:'No nos cansemos de hacer el bien; porque a su tiempo segaremos, si no desmayamos.',r:'Gálatas 6, 9',x:'La cosecha del bien viene para el que no abandona, aunque el resultado tarde en verse.'},
  {a:'fortaleza',c:'#8b2020',t:'Mi gracia es suficiente para ti; porque mi poder se perfecciona en la debilidad.',r:'2 Corintios 12, 9',x:'Dios obra con más poder donde el hombre reconoce que no puede solo.'},
  {a:'fortaleza',c:'#8b2020',t:'¿Acaso no soy yo el que te ordeno que seas fuerte y valiente? No temas ni te acobardes, porque el Señor, tu Dios, estará contigo dondequiera que vayas.',r:'Josué 1, 9',x:'La valentía bíblica no es ausencia de miedo: es avanzar sabiendo que Dios acompaña.'},
  // PAZ
  {a:'paz',c:'#4a8c8c',t:'Les dejo la paz, les doy mi paz, pero no como la da el mundo.',r:'Juan 14, 27',x:'Jesús distingue su paz de la paz mundana: es don interior que no depende de circunstancias.'},
  {a:'paz',c:'#4a8c8c',t:'La paz de Dios, que supera todo lo que podemos pensar, tomará bajo su cuidado los corazones y los pensamientos de ustedes en Cristo Jesús.',r:'Filipenses 4, 7',x:'Una paz que supera la comprensión racional: es don sobrenatural.'},
  {a:'paz',c:'#4a8c8c',t:'Felices los que trabajan por la paz, porque serán llamados hijos de Dios.',r:'Mateo 5, 9',x:'De las Bienaventuranzas: la paz no solo se recibe, también se construye.'},
  {a:'paz',c:'#4a8c8c',t:'Tú guardarás en completa paz a aquel cuyo pensamiento en ti persevera, porque en ti ha confiado.',r:'Isaías 26, 3',x:'La paz interior nace de mantener la mente anclada en Dios, no en las circunstancias.'},
  {a:'paz',c:'#4a8c8c',t:'¡Que no se inquiete el corazón de ustedes, ni tengan miedo!',r:'Juan 14, 27',x:'Jesús habla horas antes de su muerte: la serenidad que ofrece va más allá de cualquier tormenta.'},
  {a:'paz',c:'#4a8c8c',t:'En el mundo tendrán que sufrir; pero tengan valor: yo he vencido al mundo.',r:'Juan 16, 33',x:'Jesús no promete ausencia de dificultades sino la certeza de una victoria ya alcanzada.'},
  // PERDÓN
  {a:'perdon',c:'#6b4c8c',t:'El Señor es bondadoso y compasivo, lento para enojarse y de gran misericordia.',r:'Salmos 103, 8',x:'Uno de los textos más bellos sobre la misericordia divina en el Antiguo Testamento.'},
  {a:'perdon',c:'#6b4c8c',t:'Si confesamos nuestros pecados, él es fiel y justo: nos los perdonará.',r:'1 Juan 1, 9',x:'La confesión sincera encuentra siempre la misericordia de Dios.'},
  {a:'perdon',c:'#6b4c8c',t:'Perdónense mutuamente, como Dios los perdonó en Cristo.',r:'Efesios 4, 32',x:'El perdón humano tiene su modelo y su fuente en el perdón divino.'},
  {a:'perdon',c:'#6b4c8c',t:'¿Qué Dios como tú, que perdona la maldad y olvida el pecado del remanente de su heredad?',r:'Miqueas 7, 18',x:'El profeta se asombra ante un Dios que no solo perdona sino que olvida.'},
  {a:'perdon',c:'#6b4c8c',t:'Aunque sus pecados sean como la grana, quedarán blancos como la nieve.',r:'Isaías 1, 18',x:'La imagen es total: el color más difícil de quitar, convertido en la blancura más pura.'},
  {a:'perdon',c:'#6b4c8c',t:'Feliz aquel cuya falta ha sido perdonada, cuyo pecado ha sido borrado.',r:'Salmos 32, 1',x:'David canta la dicha del perdón recibido: la culpa cubierta es el comienzo de la paz.'},
  {a:'perdon',c:'#6b4c8c',t:'Como el Padre me amó, también yo los he amado a ustedes. Permanezcan en mi amor.',r:'Juan 15, 9',x:'El amor de Jesús es la fuente del perdón: permanecer en ese amor es la vida cristiana.'},
  // FE
  {a:'fe',c:'#4a7a8c',t:'La fe es la garantía de los bienes que se esperan, la plena certeza de las realidades que no se ven.',r:'Hebreos 11, 1',x:'La definición clásica de la fe: certeza de lo invisible, fundamento de la esperanza.'},
  {a:'fe',c:'#4a7a8c',t:'Sin fe es imposible agradar a Dios, pues quien se acerca a Dios debe creer que existe.',r:'Hebreos 11, 6',x:'La fe es la condición básica de la relación con Dios.'},
  {a:'fe',c:'#4a7a8c',t:'Dios amó tanto al mundo, que entregó a su Hijo único para que todo el que cree en él no muera, sino que tenga Vida eterna.',r:'Juan 3, 16',x:'El versículo más conocido del Evangelio: síntesis del mensaje cristiano.'},
  {a:'fe',c:'#4a7a8c',t:'Todo es posible para el que cree.',r:'Marcos 9, 23',x:'Jesús lo dice ante un caso humanamente desesperado: la fe abre lo que la razón cierra.'},
  {a:'fe',c:'#4a7a8c',t:'El justo vivirá por la fe.',r:'Romanos 1, 17',x:'El principio central de San Pablo: la vida auténtica brota de la fe, no de las obras solas.'},
  {a:'fe',c:'#4a7a8c',t:'Si tienen fe del tamaño de un grano de mostaza, podrán decirle a este monte: "Trasládate de aquí para allá", y se trasladará.',r:'Mateo 17, 20',x:'No la cantidad sino la calidad y autenticidad de la fe es lo que mueve montañas.'},
  {a:'fe',c:'#4a7a8c',t:'Yo estoy junto a la puerta y llamo: si alguien oye mi voz y me abre, entraré en su casa.',r:'Apocalipsis 3, 20',x:'La fe comienza con un acto de apertura: escuchar, reconocer, abrir.'},
  // AMOR
  {a:'amor',c:'#c06080',t:'Amarás al Señor, tu Dios, con todo tu corazón, con toda tu alma y con toda tu mente. Este es el mandamiento más grande y el primero.',r:'Mateo 22, 37-38',x:'Jesús resume toda la ley en el amor: primero a Dios, y de ahí todo lo demás.'},
  {a:'amor',c:'#c06080',t:'En esto reconocerán todos que ustedes son mis discípulos: en el amor que se tengan los unos a los otros.',r:'Juan 13, 35',x:'El amor entre cristianos es la señal que identifica al discípulo, no los títulos ni las palabras.'},
  {a:'amor',c:'#c06080',t:'El amor es paciente, es servicial; el amor no es envidioso, no hace alarde, no se envanece.',r:'1 Corintios 13, 4',x:'El himno al amor de San Pablo: no es un sentimiento sino una forma concreta de vivir.'},
  {a:'amor',c:'#c06080',t:'No hay amor más grande que dar la vida por los amigos.',r:'Juan 15, 13',x:'Jesús define el amor máximo que Él mismo realizará horas después.'},
  {a:'amor',c:'#c06080',t:'El amor cubre multitud de pecados.',r:'1 Pedro 4, 8',x:'El amor no ignora el pecado; lo transforma, cura, reconcilia.'},
  {a:'amor',c:'#c06080',t:'Dios es amor, y el que permanece en el amor permanece en Dios, y Dios permanece en él.',r:'1 Juan 4, 16',x:'La definición más profunda de Dios en toda la Escritura: no que ama, sino que ES amor.'},
  // CONFIANZA
  {a:'confianza',c:'#7a9a6a',t:'Confía en el Señor con todo tu corazón, y no te apoyes en tu propia inteligencia.',r:'Proverbios 3, 5',x:'La sabiduría bíblica enseña que la inteligencia humana necesita un fundamento más alto.'},
  {a:'confianza',c:'#7a9a6a',t:'El Señor es mi pastor, nada me puede faltar.',r:'Salmos 23, 1',x:'La imagen del pastor: alguien que conoce por nombre a cada oveja y la cuida con ternura.'},
  {a:'confianza',c:'#7a9a6a',t:'Encomienda al Señor tu camino, confía en él, y él actuará.',r:'Salmos 37, 5',x:'La confianza no es pasividad: es dejar que Dios actúe mientras uno da los pasos que puede.'},
  {a:'confianza',c:'#7a9a6a',t:'La misericordia del Señor dura por siempre, para los que lo temen.',r:'Salmos 103, 17',x:'La misericordia de Dios no tiene principio ni fin: es el fundamento más firme de la confianza.'},
];

const CARDS=[
  {tema:'tristeza',c:'#6b8cba',l:'Tristeza',q:'"El Señor está cerca de los que tienen el corazón quebrantado." — Salmos 34, 18',a:'En la tradición bíblica, el corazón quebrantado no es debilidad a superar sino la disposición que más atrae la presencia de Dios. La tristeza sincera puede ser un umbral hacia lo sagrado.',h:'La tristeza puede ser el momento más cercano a Dios.'},
  {tema:'tristeza',c:'#6b8cba',l:'Tristeza',q:'"Vengan a mí todos los que están fatigados y sobrecargados, y yo les daré descanso." — Mateo 11, 28',a:'Jesús no pide que vengas cuando estés bien. Llama precisamente a los cargados. El descanso que ofrece no es ausencia de problemas sino una presencia que sostiene en medio de ellos.',h:'La invitación de Jesús va dirigida específicamente al que sufre.'},
  {tema:'alegria',c:'#c9a84c',l:'Alegría',q:'"Alégrense siempre en el Señor. Vuelvo a insistir, alégrense." — Filipenses 4, 4',a:'San Pablo escribía estas palabras desde la prisión. La alegría cristiana no nace de las circunstancias externas sino de la comunión con Cristo. Por eso puede mandarse como virtud.',h:'La alegría de la fe se puede cultivar como virtud, no depende del estado de ánimo.'},
  {tema:'alegria',c:'#c9a84c',l:'Alegría',q:'"El gozo del Señor es la fortaleza de ustedes." — Nehemías 8, 10',a:'En la renovación del pacto tras el exilio, Esdras llama al pueblo al gozo. La alegría espiritual no es superficial: es fuente de resistencia y fuerza para vivir con integridad.',h:'Alegría y fortaleza están unidos: el gozo interior sostiene en las dificultades.'},
  {tema:'miedo',c:'#8b6040',l:'Miedo',q:'"No temas, porque yo estoy contigo; no te inquietes, porque yo soy tu Dios." — Isaías 41, 10',a:'Las palabras "no temas" aparecen más de 300 veces en la Biblia. Dios no promete ausencia de peligro sino su presencia en el peligro. La cercanía divina transforma el miedo.',h:'"No temas" es el mandato más repetido en la Biblia — presencia, no ausencia del peligro.'},
  {tema:'miedo',c:'#8b6040',l:'Miedo',q:'"En el amor no hay lugar para el temor: el amor perfecto elimina el temor." — 1 Juan 4, 18',a:'San Juan enseña que el miedo y el amor operan en el alma de modo inverso. Crecer en el amor de Dios y al prójimo es el camino para vencer el temor desde adentro, no reprimiéndolo.',h:'El miedo se vence creciendo en el amor, no suprimiéndolo por voluntad.'},
  {tema:'esperanza',c:'#4a8c6b',l:'Esperanza',q:'"Los que esperan en el Señor renuevan sus fuerzas, despliegan alas como las águilas." — Isaías 40, 31',a:'El águila no vuela por su propia fuerza sino aprovechando las corrientes de aire. Así la esperanza: no es autoconfianza sino apertura a la fuerza de Dios que nos levanta.',h:'Esperar en el Señor es como el águila: no fuerza propia sino apertura a la corriente divina.'},
  {tema:'esperanza',c:'#4a8c6b',l:'Esperanza',q:'"La esperanza no quedará defraudada, porque el amor de Dios ha sido derramado en nuestros corazones." — Romanos 5, 5',a:'San Pablo distingue la esperanza cristiana del optimismo humano. El optimismo puede decepcionar; la esperanza cristiana se asienta en el amor de Dios que ya actúa en el corazón.',h:'La esperanza cristiana no es optimismo: tiene fundamento real — el amor ya presente.'},
  {tema:'fortaleza',c:'#8b2020',l:'Fortaleza',q:'"Yo lo puedo todo en aquel que me conforta." — Filipenses 4, 13',a:'Una de las frases más malinterpretadas: no significa que el cristiano puede hacer todo lo que quiera. Significa que en la comunión con Cristo hay fuerza para aceptar toda situación con serenidad.',h:'El contexto es clave: Pablo habla de aceptar toda situación, no de logros ilimitados.'},
  {tema:'fortaleza',c:'#8b2020',l:'Fortaleza',q:'"Sean fuertes y valientes. No teman, porque el Señor, su Dios, los acompaña." — Deuteronomio 31, 6',a:'Las últimas palabras de Moisés antes de su muerte. La valentía que pide no es la del héroe solitario sino la del que sabe que no está solo. La presencia de Dios transforma la debilidad.',h:'La valentía bíblica no es ausencia de miedo sino la decisión de actuar apoyándose en Dios.'},
  {tema:'paz',c:'#4a8c8c',l:'Paz',q:'"Les dejo la paz, les doy mi paz, pero no como la da el mundo." — Juan 14, 27',a:'Jesús distingue dos paces. La del mundo es frágil: depende de circunstancias favorables. Su paz es interior, no depende de las condiciones externas ni de la comprensión humana.',h:'La paz de Cristo no es ausencia de conflicto sino presencia interior que sostiene en él.'},
  {tema:'paz',c:'#4a8c8c',l:'Paz',q:'"Felices los que trabajan por la paz, porque serán llamados hijos de Dios." — Mateo 5, 9',a:'La paz no es solo algo que se recibe pasivamente: se construye activamente. Trabajar por la paz es tarea que revela la filiación divina. El que hace la paz se parece a Dios.',h:'La paz se construye, no solo se recibe. Los artesanos de paz son imagen de Dios.'},
];
