const ORACIONES=[
  {t:'Señal de la Cruz',tp:'Invocación Trinitaria',o:'Tradición apostólica. Abre y cierra toda oración católica.',tx:'En el nombre del Padre,\ny del Hijo,\ny del Espíritu Santo.\nAmén.'},
  {t:'Padre Nuestro',tp:'Oración del Señor',o:'Mateo 6, 9-13 — La única oración enseñada por Jesús mismo',tx:'Padre nuestro, que estás en el cielo,\nsantificado sea tu Nombre;\nvenga a nosotros tu Reino;\nhágase tu voluntad\nen la tierra como en el cielo.\nDanos hoy nuestro pan de cada día;\nperdona nuestras ofensas,\ncomo también nosotros perdonamos\na los que nos ofenden;\nno nos dejes caer en la tentación,\ny líbranos del mal. Amén.'},
  {t:'Ave María',tp:'Oración Mariana',o:'Lucas 1, 28.42 y tradición de la Iglesia — Oración más rezada del mundo',tx:'Dios te salve, María,\nllena eres de gracia;\nel Señor es contigo.\nBendita tú eres entre todas las mujeres\ny bendito es el fruto de tu vientre, Jesús.\n\nSanta María, Madre de Dios,\nruega por nosotros, pecadores,\nahora y en la hora de nuestra muerte. Amén.'},
  {t:'Gloria al Padre',tp:'Doxología Trinitaria',o:'Tradición apostólica. Se reza al final de cada misterio del Rosario.',tx:'Gloria al Padre,\ny al Hijo,\ny al Espíritu Santo.\nComo era en el principio,\nahora y siempre,\ny por los siglos de los siglos. Amén.'},
  {t:'Oh Jesús mío',tp:'Oración de Fátima',o:'Pedida por la Virgen a los pastorcitos de Fátima en 1917. Se reza después del Gloria de cada decena del Rosario.',tx:'Oh Jesús mío,\nperdona nuestros pecados,\nlíbranos del fuego del infierno,\nlleva al cielo a todas las almas,\nespecialmente a las más necesitadas de tu misericordia. Amén.'},
  {t:'Credo Apostólico',tp:'Profesión de Fe',o:'Síntesis de la fe de los apóstoles. Se usa en el Bautismo y el Rosario.',tx:'Creo en Dios, Padre todopoderoso,\nCreador del cielo y de la tierra.\n\nCreo en Jesucristo, su único Hijo, nuestro Señor,\nque fue concebido por obra y gracia del Espíritu Santo,\nnació de Santa María Virgen,\npadeció bajo el poder de Poncio Pilato,\nfue crucificado, muerto y sepultado,\ndescendió a los infiernos,\nal tercer día resucitó de entre los muertos,\nsubió a los cielos\ny está sentado a la derecha de Dios, Padre todopoderoso.\nDesde allí ha de venir a juzgar a vivos y muertos.\n\nCreo en el Espíritu Santo,\nla santa Iglesia católica,\nla comunión de los santos,\nel perdón de los pecados,\nla resurrección de la carne\ny la vida eterna. Amén.'},
  {t:'Salve Regina',tp:'Antífona Mariana',o:'Siglo XI. Se reza al finalizar el Rosario y en la Liturgia de las Horas.',tx:'Dios te salve, Reina y Madre de misericordia,\nvida, dulzura y esperanza nuestra; Dios te salve.\nA ti clamamos los desterrados hijos de Eva;\na ti suspiramos, gimiendo y llorando\nen este valle de lágrimas.\n\nEa, pues, Señora, abogada nuestra,\nvuelve a nosotros esos tus ojos misericordiosos;\ny después de este destierro, muéstranos a Jesús,\nfruto bendito de tu vientre.\n\nOh clementísima, oh piadosa,\noh dulce Virgen María. Amén.'},
  {t:'Ángelus',tp:'Oración del Mediodía',o:'Tradición medieval. Se reza a las 6, 12 y 18 h al tañido de las campanas.',tx:'El ángel del Señor anunció a María,\ny ella concibió por obra del Espíritu Santo.\n— Dios te salve María... (Ave María)\n\nHe aquí la esclava del Señor,\nhágase en mí según tu palabra.\n— Dios te salve María... (Ave María)\n\nY el Verbo se hizo carne\ny habitó entre nosotros.\n— Dios te salve María... (Ave María)\n\nRuega por nosotros, Santa Madre de Dios,\npara que seamos dignos de alcanzar\nlas promesas de Jesucristo.\n\nOremos: Derrama, Señor, tu gracia sobre nosotros,\nque hemos conocido, por el anuncio del ángel,\nla Encarnación de tu Hijo Jesucristo,\npara que lleguemos por su Pasión y su Cruz\na la gloria de la Resurrección.\nPor Jesucristo Nuestro Señor. Amén.'},
  {t:'Oración de San Francisco',tp:'Oración de Paz',o:'Atribuida a San Francisco de Asís (s. XIII). Una de las oraciones más conocidas del mundo.',tx:'Señor, hazme instrumento de tu paz.\nDonde haya odio, lleve yo el amor;\ndonde haya ofensa, el perdón;\ndonde haya discordia, la unión;\ndonde haya duda, la fe;\ndonde haya error, la verdad;\ndonde haya desesperanza, la esperanza;\ndonde haya tristeza, la alegría;\ndonde haya sombras, tu luz.\n\nOh Divino Maestro,\nconcédeme que no busque tanto\nser consolado, como consolar;\nser comprendido, como comprender;\nser amado, como amar.\n\nPorque dando se recibe,\nolvidando se encuentra,\nperdonando se es perdonado,\ny muriendo se resucita a la vida eterna. Amén.'},
  {t:'Acto de Contrición',tp:'Oración Penitencial',o:'Tradición de la Iglesia. Se reza antes o después del Sacramento de la Reconciliación.',tx:'Dios mío,\nme arrepiento de todo corazón de todos mis pecados\ny los aborrezco,\nporque al pecar, no solo merezco las penas\nestablecidas por ti justamente,\nsino principalmente porque te ofendí a ti,\nsumo Bien y digno de amor por encima de todas las cosas.\n\nPor eso propongo firmemente,\ncon ayuda de tu gracia,\nno pecar más en adelante\ny huir de las ocasiones de pecado.\nAmén.'},
  {t:'Pésame',tp:'Acto de Contrición Popular',o:'Forma breve y tradicional del Acto de Contrición. Se reza al comienzo del Rosario, después de la Señal de la Cruz.',tx:'Pésame, Dios mío,\ny me arrepiento de todo corazón de haberos ofendido.\nPésame por el infierno que merecí\ny por el cielo que perdí;\npero mucho más me pesa,\nporque pecando ofendí a un Dios tan bueno y tan grande como Vos.\nAntes querría haber muerto que haberos ofendido,\ny propongo firmemente no pecar más\ny evitar todas las ocasiones próximas de pecado. Amén.'},
  {t:'Ofrecimiento del Rosario',tp:'Acto de Contrición y Ofrecimiento',o:'Tradición devocional. Se reza al comienzo del Rosario, después de la Señal de la Cruz, para ofrecerlo por una intención.',tx:'Dios mío, me arrepiento de todo corazón de todos mis pecados y los aborrezco,\nporque al pecar no solo merezco las penas que justamente estableciste,\nsino principalmente porque te ofendí, sumo Bien, que mereces todo mi amor.\n\nPor eso propongo firmemente, con la ayuda de tu gracia,\nno pecar más y evitar las ocasiones próximas de pecado.\n\nOfrezco este Santo Rosario por mis intenciones,\npor la Iglesia, por el Santo Padre y sus intenciones,\npor mi familia, por las personas que amo\ny por todas aquellas que necesitan de Dios.\n\nSanta María, Madre de Dios, ruega por nosotros. Amén.'},
  {t:'Oración final',tp:'Colecta del Rosario',o:'Oración tradicional con la que se cierra el rezo del Santo Rosario, después de la Salve.',tx:'Oh Dios, cuyo Hijo unigénito,\ncon su vida, muerte y resurrección,\nnos alcanzó el premio de la vida eterna;\n\nconcédenos que, meditando estos misterios\ndel Santísimo Rosario de la Virgen María,\nimitemos lo que contienen\ny alcancemos lo que prometen.\n\nPor el mismo Jesucristo, nuestro Señor. Amén.'},
  {t:'Sub Tuum Praesidium',tp:'Oración Mariana Antigua',o:'Siglo III d.C. Es la oración mariana más antigua conservada, hallada en un papiro egipcio de Oxirrinco.',tx:'Bajo tu amparo nos acogemos,\nSanta Madre de Dios.\nNo deseches las súplicas\nque te dirigimos en nuestras necesidades,\nantes bien líbranos siempre\nde todos los peligros,\noh Virgen gloriosa y bendita. Amén.'},
  {t:'Oración a San Miguel Arcángel',tp:'Oración de Protección',o:'Compuesta por el Papa León XIII en 1886. Se reza pidiendo protección contra el mal.',tx:'San Miguel Arcángel,\ndefiéndenos en la batalla;\nsé nuestro amparo\ncontra la perversidad y asechanzas del demonio.\n\nReprímalo Dios, pedimos suplicantes,\ny tú, Príncipe de la milicia celestial,\narroja al infierno con el divino poder\na Satanás y a los demás espíritus malignos\nque andan dispersos por el mundo\npara la perdición de las almas. Amén.'},
  {t:'Oración al Espíritu Santo',tp:'Oración de Pentecostés',o:'Veni Sancte Spiritus. Secuencia de Pentecostés, usada también antes de decisiones importantes.',tx:'Ven, Espíritu Santo,\nllena los corazones de tus fieles\ny enciende en ellos el fuego de tu amor.\n\nEnvía, Señor, tu Espíritu,\ny renueva la faz de la tierra.\n\nOremos: Oh Dios, que has instruido los corazones de los fieles\ncon la luz del Espíritu Santo,\nconcédenos que sepamos gustar del bien por el mismo Espíritu,\ny gozar siempre de sus divinos consuelos.\nPor Jesucristo, nuestro Señor. Amén.'},
  {t:'Oración a Santa Mónica',tp:'Oración por los Hijos',o:'Madre de San Agustín (s. IV). Patrona de las madres cristianas que ruegan por la conversión de sus hijos.',tx:'Señor, que a través de las lágrimas\ny la oración perseverante de Santa Mónica\nalcanzaste la conversión de su hijo Agustín,\nconcédenos, por su intercesión,\nla gracia de saber perseverar en la oración\npor nuestros seres queridos,\npara que también ellos encuentren tu camino.\n\nQue su ejemplo de paciencia, fe y amor maternal\nnos enseñe a no desfallecer nunca en la esperanza.\nPor Jesucristo, nuestro Señor. Amén.'},
  {t:'Oración a San Padre Pío',tp:'Oración de Intercesión',o:'San Pío de Pietrelcina (1887-1968), fraile capuchino que llevó los estigmas de Cristo.',tx:'Oh Dios, que adornaste al sacerdote San Pío\ncon la gracia singular de participar\nen la Pasión de tu Hijo,\nconcédenos, por su intercesión,\nque, unidos a Cristo crucificado,\nte sirvamos con caridad constante\npara alcanzar la gloria eterna.\n\nSan Pío, tú que llevaste en tu cuerpo\nlas llagas de Cristo,\nruega por nosotros,\npara que sepamos abrazar la cruz de cada día\ncon fe y amor. Por Jesucristo, nuestro Señor. Amén.'},
  {t:'Misterios del Santo Rosario',tp:'Guía de los Cuatro Misterios',o:'Los veinte episodios del Evangelio contemplados en el Rosario, agrupados de a cinco por día de la semana.',tx:'GOZOSOS (lunes y sábado)\nLa Anunciación del Ángel a María\nLa Visitación de María a su prima Isabel\nEl Nacimiento de Jesús en Belén\nLa Presentación de Jesús en el Templo\nEl Niño Jesús perdido y hallado en el Templo\n\nLUMINOSOS (jueves)\nEl Bautismo de Jesús en el Jordán\nLas Bodas de Caná\nEl anuncio del Reino de Dios y la llamada a la conversión\nLa Transfiguración del Señor\nLa Institución de la Eucaristía\n\nDOLOROSOS (martes y viernes)\nLa Oración de Jesús en el Huerto\nLa Flagelación del Señor atado a la columna\nLa Coronación de espinas\nJesús con la cruz a cuestas camino al Calvario\nLa Crucifixión y muerte de Jesús\n\nGLORIOSOS (miércoles y domingo)\nLa Resurrección del Señor\nLa Ascensión del Señor a los cielos\nLa Venida del Espíritu Santo sobre María y los Apóstoles\nLa Asunción de María al cielo\nLa Coronación de María como Reina del cielo y de la tierra'},
  {t:'Oración por los Difuntos',tp:'Oración de Sufragio',o:'Tradición litúrgica romana. Se reza recordando a los fieles difuntos, especialmente el 2 de noviembre.',tx:'Dales, Señor, el descanso eterno,\ny brille para ellos la luz perpetua.\nDescansen en paz. Amén.\n\nOremos: Te rogamos, Señor,\nque las almas de tus siervos difuntos,\npurificadas de sus pecados,\nalcancen la resurrección\ny la vida eterna en la gloria de tu Reino.\nPor Jesucristo, nuestro Señor. Amén.'},
  {t:'Oración por las Benditas Almas del Purgatorio',tp:'Oración de Sufragio',o:'Tradición devocional católica, ligada a la doctrina del Purgatorio y la comunión de los santos.',tx:'Oh Dios, Creador y Redentor de todos los fieles,\nconcede a las almas de tus siervos difuntos\nla remisión de todos sus pecados,\npara que alcancen, por nuestras piadosas súplicas,\nel perdón que siempre desearon.\n\nTú que vives y reinas por los siglos de los siglos. Amén.\n\nEterno descanso concédeles, Señor,\ny brille para ellas la luz perpetua.\nQue descansen en paz. Amén.'},
];
